public int findMinFibonacciNumbers(int k) {
    int[] fibonacciNumbers = { 1, 1 };
    int i = 2;
    while (fibonacciNumbers[i - 1] + fibonacciNumbers[i - 2] <= k) {
        fibonacciNumbers[i] = fibonacciNumbers[i - 1] + fibonacciNumbers[i - 2];
        i++;
    }
    int count = 0;
    while (k > 0) {
        for (int j = i - 1; j >= 0; j--) {
            if (fibonacciNumbers[j] <= k) {
                k -= fibonacciNumbers[j];
                count++;
            }
        }
    }
    return count;
}
```

